use eris::dom::Document;
use eris::script::{Runtime,Value};
use std::io::{self,Read};
fn main() {
    let mut input=String::new();io::stdin().read_to_string(&mut input).unwrap();
    for record in input.split('\0').filter(|s|!s.is_empty()) {
        let (mode,source)=record.split_once('\n').unwrap();
        let mut runtime=Runtime::new();let mut doc=Document::parse("");
        let result=if mode=="strict"{runtime.execute_strict(source,&mut doc)}else{runtime.execute(source,&mut doc)};
        match result {
            Ok(Value::Undefined)=>println!("undefined"),
            Ok(Value::Null)=>println!("null"),
            Ok(Value::Bool(value))=>println!("bool:{value}"),
            Ok(Value::Number(value))=>println!("number:{:016x}",value.to_bits()),
            Ok(Value::String(value))=>println!("string:{:?}",value.units()),
            Ok(value)=>println!("object:{value:?}"),
            Err(error)=>println!("error:{}:{error}",error.name()),
        }
    }
}
